 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){if(world==null)return;try{if(!NativeNavigationTableChecks.completeDrops(world))return;if(++ticks>1500)throw new AssertionError("navigation data timeout stage="+stage);var press=press();if(stage==1){if(!press.formed()||!press.available())return;var ingot=BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("vandorlabs","programmable_matter_ingot"));need(press.canPlaceItem(0,new ItemStack(ingot)),"Press input accepts one Matter Ingot");press.configureRedstone(0,com.vandorlabs.redstone.ChannelList.EMPTY);press.setItem(0,new ItemStack(ingot));var battery=new ItemStack(NativeRackBindings.BATTERY);NativeBatteryModule.transfer(battery,10000,false,true);press.setItem(2,battery);stage=2;}else if(stage==2){if(ticks<20)return;need(!press.processing()&&press.getItem(0).getCount()==1&&press.batteryEnergy()==10000,"missing Catalog chip cannot spend input/RF");press.setItem(3,NativeChipTypes.variant("catalog"));stage=3;}else if(stage==3){if(press.processing()||press.getItem(1).isEmpty())return;need(press.getItem(0).isEmpty()&&NativeNavigationModuleData.item(press.getItem(1))&&press.batteryEnergy()==2000,"manufacture one Module from1Ingot/8000RF");var raw=press.saveWithFullMetadata(world.registryAccess());var copy=new NativeBuilderEntity(pos,press.getBlockState());copy.setLevel(world);copy.loadWithComponents(raw,world.registryAccess());need(!copy.inert()&&NativeBuilderData.sameSnapshots(raw,copy.saveWithFullMetadata(world.registryAccess())),"Press saved module inventory strict roundtrip");setupTower();stage=4;}else if(stage==4){if(!press.formed()||!press.available())return;press.selectDesign(recipe);press.setItem(0,new ItemStack(BuiltInRegistries.BLOCK.get(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("vandorlabs","programmable_matter_block"))));var battery=new ItemStack(NativeRackBindings.BATTERY);NativeBatteryModule.transfer(battery,10000,false,true);press.setItem(2,battery);press.setItem(3,NativeChipTypes.variant("catalog"));press.configureRedstone(0,com.vandorlabs.redstone.ChannelList.EMPTY);stage=5;}else if(stage==5){if(press.processing()||press.getItem(1).isEmpty())return;need(ItemStack.isSameItemSameComponents(press.getItem(1),NativeBuilderProducts.result(recipe))&&press.batteryEnergy()==2000,"Tower observer output exact8000RF recipe="+recipe);press.removeItem(1,1);if(++recipe<5){stage=4;return;}System.out.println("[vandorlabs][navigation-data] PASS checks="+checks+" actualAsyncPressAndTowerFormation/Catalog/1Ingot/8000RF/ObserverCores/1024Circles/ExactEdges/DimensionBind/OfflinePayload/NoChunks/21ByteRequest/59ByteKnownRevision");world=null;e.getServer().halt(false);}}catch(Throwable bad){fail(bad);}}
